"""Read-only engineering scorecard, separate from runtime clinical evidence."""
import json


def page(report):
    data=json.dumps(report,allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere workflow evaluation</title>
<style>body{margin:0;background:#f2f5f4;color:#18372f;font:16px/1.5 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:35px}a{color:#08685d}h1{font-size:34px;letter-spacing:-1px;margin-bottom:8px}h2{margin-top:0;font-size:23px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:2px}p{max-width:940px}.notice{background:#fff1d5;padding:15px;border-left:4px solid #b68527}.counts{display:flex;gap:18px;margin:24px 0}.counts div{background:white;border:1px solid #ccd8d3;border-radius:8px;padding:15px 22px}.counts strong{font-size:25px;display:block}table{width:100%;border-collapse:collapse;background:white}th,td{padding:11px;text-align:left;border:1px solid #d4ded9;font-size:13px}.passed,.checked{background:#e6f3ea}.failed,.input_mismatch,.lineage_failure,.runtime_error,.coverage_gap,.selection_gap,.incomplete,.control_failure{background:#fbe8e4}.blocked,.unassessed,.not_comparable,.connected_review_unvalidated,.isolated_diagnostic,.executed_unvalidated,.unsupported,.blocked_by_scope,.not_run,.scope_not_verified,.upstream_unavailable{background:#fff3d9}article{background:white;border:1px solid #d4ded9;border-radius:8px;padding:22px;margin-top:20px}details{border-top:1px solid #e2e8e5;padding:12px 0}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;color:#364a42}.scroll{overflow:auto}.muted{color:#5b6d64;font-size:14px}button{font:inherit}footer{padding:25px 0}</style>
<main><a href="/stack">← Agere workspace</a><p class="eyebrow">Engineering development / release acceptance</p><h1>Release evidence and remaining work</h1><p id="scope"></p><p class="notice">These saved development executions cover declared workflows, not every current capability. Receipt integrity is checked when this page opens; opening the page does not rerun the workflows. Software execution and clinical quality are separate. Qualification and external deployment requirements remain separate. Passing isolated checks cannot establish full workflow completion. These are development examples, not independent clinical validation.</p><div class="counts" id="counts"></div><div class="scroll"><table id="matrix"></table></div><p class="muted">Green: declared stage checks pass. Amber: unvalidated, isolated or unavailable. Red: measured error or coverage gap. Read each stage’s limits below.</p><article id="release"><h2>Full release requirements</h2><p class="muted">Individual examples do not establish population, VBC, financial or deployment readiness. Unassessed means the required whole-workflow evidence is not attached; isolated components may already exist.</p><div class="scroll"><table id="release-matrix"></table></div></article><article id="selection"><h2>Evidence-selection activation decision</h2></article><article id="change"><h2>Planner contract progress</h2></article><article id="gaps"><h2>Measured gaps</h2></article><section id="cases"></section><footer class="muted" id="footer"></footer></main>
<script type="application/json" id="report">'''+data+'''</script><script>
const report=JSON.parse(document.getElementById('report').textContent);const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};const human=s=>String(s).replaceAll('_',' ');document.getElementById('scope').textContent=report.scope;
for(const [n,label] of [[report.workflow_count,'development workflows'],[report.complete_workflows,'individual workflows with passing saved traces'],[report.connected_answer_handoffs||0,'answer-linked internal handoffs']]){const d=node('div');d.append(node('strong',n),node('span',label));document.getElementById('counts').append(d)}
const release=report.release_acceptance,rt=document.getElementById('release-matrix');
if(release){const h=node('tr');for(const label of ['Requirement','Acceptance axis','Status','Required evidence'])h.append(node('th',label));rt.append(h);for(const r of release.requirements){const tr=node('tr');for(const value of [human(r.id),human(r.axis),human(r.status),r.remaining_evidence||'Declared checks passed'])tr.append(node('td',value));tr.children[2].className=r.status;rt.append(tr)}for(const r of release.requirements){const d=node('details');d.open=Boolean(r.evidence_error);d.append(node('summary',human(r.id)+' — '+human(r.status)));if(r.evidence_error){const p=node('p',r.evidence_error.detail);p.className='notice';d.append(p,node('p','Receipt: '+r.evidence_error.receipt))}if(r.verification_scope)d.append(node('p',r.verification_scope));if(r.workflow_verification){const v=r.workflow_verification;d.open=true;d.append(node('h3','Latest saved workflow replay'),node('p','Recorded '+v.recorded_at+'. '+v.limits));const t=node('table'),h=node('tr');for(const label of ['Workflow','Replay status','Scope / remaining dependency'])h.append(node('th',label));t.append(h);for(const row of v.rows){const tr=node('tr');for(const value of [human(row.case),human(row.current_status),row.reason||(row.reasons||[]).join('; ')||(row.population?row.population+' people; scope retained':'Saved work retained')])tr.append(node('td',value));tr.children[1].className=row.current_status==='current'?'passed':'blocked';t.append(tr)}const scroll=node('div');scroll.className='scroll';scroll.append(t);d.append(scroll)}for(const check of r.observations){const p=node('p',human(check.id)+': '+human(check.status)+(check.detail?' — '+check.detail:''));p.className=check.status;d.append(p)}d.append(node('pre',JSON.stringify(r.observations,null,2)));document.getElementById('release').append(d)}document.getElementById('release').append(node('p','Local engineering: '+release.engineering_requirements_passed+' of '+release.engineering_requirements_total+' requirements passed. '+release.limitations))}else{document.getElementById('release').append(node('p','This historical report has no computed release contract.'))}
const selection=report.source_selection_decision,selectionBox=document.getElementById('selection');
if(selection){selectionBox.append(node('p',selection.summary));if(selection.evidence_verified){selectionBox.append(node('p','Default: '+human(selection.default)+'. Broader candidate: not promoted. These are machine-authored documentary diagnostics, not clinician adjudication.'));const t=node('table'),h=node('tr');for(const label of ['Question','Candidate execution','Added direct / supporting / off-question / uncertain records','Received reference records outside scope','Saved-answer API estimate: default → candidate'])h.append(node('th',label));t.append(h);const price=n=>n===null||n===undefined?'unknown':'$'+n.toFixed(3);for(const c of selection.cases){const tr=node('tr'),counts=c.additional_record_counts;for(const v of [human(c.case),human(c.candidate_status),['direct','supporting','off_question','uncertain'].map(k=>counts[k]||0).join(' / '),c.missing_expanded_reference_records,price(c.baseline.inference_estimate_usd)+' → '+price(c.candidate.inference_estimate_usd)])tr.append(node('td',v));t.append(tr);const d=node('details');d.append(node('summary',human(c.case)+' — measured limitations'));for(const reason of c.reasons)d.append(node('p',reason));if(c.candidate.answer_id){const a=node('a','Open candidate interpretation for review');a.href='/stack?case='+encodeURIComponent(c.candidate.answer_id);d.append(a)}selectionBox.append(d)}const scroll=node('div');scroll.className='scroll';scroll.append(t);selectionBox.insertBefore(scroll,selectionBox.children[2]);selectionBox.append(node('p',selection.cost.new_inference_requests+' new inference requests; '+selection.cost.failed_requests+' failed. Recorded-price API estimate including the failure: '+price(selection.cost.estimated_api_usd_including_failed)+'. Total cost including human review remains unknown.'),node('p',selection.cost.limits));}}else{selectionBox.append(node('p','No current activation decision attached.'))}
const stages=Object.keys(report.stage_counts),table=document.getElementById('matrix'),head=node('tr');head.append(node('th','Workflow'));for(const s of stages)head.append(node('th',human(s)));table.append(head);
if(report.planner_comparison){const p=report.planner_comparison;document.getElementById('change').append(node('p',(p.before.runtime_error||0)+' of '+report.workflow_count+' planning cases failed before the correction; '+(p.current.runtime_error||0)+' still fail. '+(p.current.executed_unvalidated||0)+' executed with patient scope verified and clinical quality unvalidated.'),node('p',p.meaning))}
if(report.previous_release_source_interpretation){const before=report.previous_release_source_interpretation,current=report.stage_counts.source_interpretation;document.getElementById('change').append(node('p','Source interpretation: '+(before.executed_unvalidated||0)+' → '+(current.executed_unvalidated||0)+' executed; '+(current.runtime_error||0)+' runtime errors and '+(current.blocked_by_scope||0)+' blocked by source scope. Source and clinical adequacy remain unvalidated.'))}
if(report.usage_accounting){const u=report.usage_accounting,c=u.cost;document.getElementById('change').append(node('p',u.new_provider_calls+' provider requests in the recorded source-answer release. '+(c.estimated_usd===null?'Some usage remains unpriced.':'Estimated API cost $'+c.estimated_usd.toFixed(3)+' including failed responses.')+' Usage is accounted for; spend is uncapped. Costs are not invoice verified.'))}
for(const gap of report.known_gaps||[])document.getElementById('gaps').append(node('p',gap));
for(const c of report.cases){const row=node('tr'),a=node('a',human(c.id));a.href='#'+c.id;const name=node('th');name.append(a);row.append(name);for(const s of stages){const v=c.stages[s],cell=node('td',human(v.status));cell.className=v.status;row.append(cell)}table.append(row);
 const article=node('article');article.id=c.id;article.append(node('h2',human(c.id)+' · '+c.patient),node('p',c.question));
 if(c.acceptance){const d=node('details');d.open=true;d.append(node('summary','Engineering acceptance — '+human(c.acceptance.status)));for(const check of c.acceptance.checks){const p=node('p',human(check.id)+': '+human(check.status)+' — '+check.detail);p.className=check.status;d.append(p)}d.append(node('p',c.acceptance.meaning),node('pre',JSON.stringify(c.acceptance,null,2)));article.append(d)}
 for(const [s,v] of Object.entries(c.stages)){const d=node('details'),sum=node('summary',human(s)+' — '+human(v.status));d.append(sum,node('p',v.detail));if(v.error)d.append(node('p',v.error));d.append(node('pre',JSON.stringify(v,null,2)));if(v.answer_id){const link=node('a','Open saved interpretation');link.href='/stack?case='+encodeURIComponent(v.answer_id);d.append(link)}article.append(d)}document.getElementById('cases').append(article)}
document.getElementById('footer').textContent=report.timing_note+' '+report.completion_rule;
</script></html>'''
